import assert from "node:assert/strict";
import {createElement} from "react";
import {renderToStaticMarkup} from "react-dom/server";
import type {Block} from "../../src/core/types";
import type {GeneratedBody} from "../../src/core/generators/definition";
import {Legacy2018TechnicalScheduleFigure} from "../../src/ui/Legacy2018TechnicalScheduleFigures";
import {legacy2018TechnicalScheduleFacts as facts} from "./legacy-2018-technical-schedule-review";
import {technicalAttr as attr} from "./legacy-2018-technical-trace-oracle";
const nums=(s:string,keys:string[])=>keys.map(k=>Number(attr(s,k)));
export function legacy2018TechnicalScheduleSvg(b:Block){assert(b.type==="diagram"&&b.scene.kind==="source_figure");return renderToStaticMarkup(createElement(Legacy2018TechnicalScheduleFigure,{profile:b.scene.profile,values:b.scene.values,caption:b.caption??""}));}
/** Event-driven independent solver: jump to CPU completion or I/O completion,
 * update the ready set, and select anew. Production advances all tasks by ticks. */
export function independent2018Schedule(d:number[][],order=[0,1,2],preempt=true){const tasks=d.map(row=>({phase:0,cpu:row[0],until:Infinity})),rows=Array.from({length:3},()=>Array(7).fill(-1));let t=0,running=-1;while(t<10){const ready=order.filter(i=>tasks[i].phase===0||tasks[i].phase===2);if(preempt||!ready.includes(running))running=ready[0]??-1;const next=Math.min(10,running===-1?Infinity:t+tasks[running].cpu,...tasks.filter(q=>q.phase===1).map(q=>q.until));assert(next>t&&Number.isFinite(next));for(let i=0;i<3;i++){const state=tasks[i].phase===3?3:tasks[i].phase===1?1:i===running?0:2;for(let slot=Math.max(3,t);slot<next;slot++)rows[i][slot-3]=state;}if(running!==-1){const job=tasks[running];job.cpu-=next-t;if(job.cpu===0){if(job.phase===0){job.phase=1;job.until=next+d[running][1];}else job.phase=3;}}for(let i=0;i<3;i++)if(tasks[i].phase===1&&tasks[i].until===next){tasks[i].phase=2;tasks[i].cpu=d[i][2];tasks[i].until=Infinity;}t=next;}assert(rows.every(r=>r.every(n=>n>=0)));return rows;}
const independentParallel=(d:number[][])=>d.map(row=>Array.from({length:7},(_,i)=>{const t=i+3;return t<row[0]?0:t<row[0]+row[1]?1:t<row.reduce((a,b)=>a+b,0)?0:3;}));
/** Reconstruct states from visible text plus interval endpoints/dash, rather
 * than trusting scene values. Every task has exactly seven covered cells. */
export function legacy2018ReadSchedule(svg:string){const axis=svg.match(/<line\b([^>]*data-time-axis="main"[^>]*)/);assert(axis);assert.deepEqual(nums(axis[1],["x1","y1","x2","y2"]),[145,70,775,70]);const labels=[...svg.matchAll(/<text\b([^>]*data-time-label="[^"]*"[^>]*)>([^<]*)<\/text>/g)];assert.equal(labels.length,8);labels.forEach((m,i)=>{assert.equal(m[2],String(i+3));assert.deepEqual(nums(m[1],["x","y"]),[145+i*90,43]);});const unit=[...svg.matchAll(/<text\b([^>]*)>([^<]*)<\/text>/g)].find(m=>m[2]===facts.timeUnitLabel.text);assert(unit);assert.deepEqual(nums(unit[1],["x","y"]),[facts.timeUnitLabel.x,facts.timeUnitLabel.y]);const groups=svg.split('<g data-task="').slice(1);assert.equal(groups.length,3);return groups.map((raw,row)=>{assert(raw.startsWith(`${"ABC"[row]}"`));const label=raw.match(/<text\b([^>]*)>([^<]*)<\/text>/);assert(label);const fixed=facts.taskLabels[row];assert.equal(label[2],fixed.text);assert.deepEqual(nums(label[1],["x","y"]),[fixed.x,fixed.y]);const cells=Array(7).fill(-1),y=fixed.y;const runs=[...raw.matchAll(/<g data-run="[^"]*">([\s\S]*?)<\/g>/g)];for(const run of runs){const lines=[...run[1].matchAll(/<line\b([^>]*)/g)];assert.equal(lines.length,3);const [a,b,c,d]=nums(lines[0][1],["x1","y1","x2","y2"]);assert.equal(b,y);assert.equal(d,y);const start=(a-145)/90,end=(c-145)/90;assert(Number.isInteger(start)&&Number.isInteger(end)&&start>=0&&end<=7&&start<end);assert.deepEqual(nums(lines[1][1],["x1","y1","x2","y2"]),[a,y-6,a,y+6]);assert.deepEqual(nums(lines[2][1],["x1","y1","x2","y2"]),[c,y-6,c,y+6]);const label=run[1].match(/<text\b([^>]*)>([^<]*)<\/text>/);assert(label);const state=["CPU","I/O","待ち"].indexOf(label[2]);assert(state>=0);assert.deepEqual(nums(label[1],["x","y"]),[(a+c)/2,y-18]);if(state===2)assert.equal(attr(lines[0][1],"stroke-dasharray"),"7 5");else assert(!lines[0][1].includes("stroke-dasharray"));for(let i=start;i<end;i++){assert.equal(cells[i],-1);cells[i]=state;}}
 const complete=raw.match(/<text\b([^>]*data-completed="label"[^>]*)>完了<\/text>/);if(complete){const [cx,cy]=nums(complete[1],["x","y"]);assert.equal(cy,y-18);const start=(cx-12-145)/90;assert(Number.isInteger(start)&&start>=0&&start<7);for(let i=start;i<7;i++){assert.equal(cells[i],-1);cells[i]=3;}}assert(cells.every(n=>n>=0));return cells;});}
export function legacy2018TechnicalScheduleOracle(b:GeneratedBody,v:number[]){assert.equal(v.length,1);const d=facts.durations[v[0]];assert(d);assert.equal(b.prompt.length,3);assert(b.prompt[0].type==="paragraph"&&b.prompt[1].type==="paragraph");assert.equal(b.prompt[0].text,facts.stem);assert.equal(b.prompt[1].text,facts.explicitPolicy);const table=b.prompt[2];assert(table.type==="table");assert.equal(table.caption,"タスクの優先度と単独実行時の動作順序・処理時間（ミリ秒）");assert.deepEqual(table.columns,["タスク","優先度","単独実行時の動作順序と処理時間（ミリ秒）"]);assert.deepEqual(table.rows,d.map((row,i)=>["ABC"[i],["高","中","低"][i],`CPU(${row[0]}) → I/O(${row[1]}) → CPU(${row[2]})`]));assert.equal(b.choices.length,4);const actual=b.choices.map(bs=>{assert.equal(bs.length,1);return legacy2018ReadSchedule(legacy2018TechnicalScheduleSvg(bs[0]));}),correct=independent2018Schedule(d);if(v[0]===0)assert.deepEqual(actual,facts.originalCharts);else assert.deepEqual(actual,[independent2018Schedule(d,[1,0,2]),independent2018Schedule(d,[0,1,2],false),correct,independentParallel(d)]);assert.equal(new Set(actual.map(a=>a.flat().join(""))).size,4);const truth=actual.map(a=>a.flat().every((s,i)=>s===correct.flat()[i]));assert.equal(truth.filter(Boolean).length,1);assert.equal(b.correctIndex,truth.indexOf(true));for(let i=0;i<7;i++)assert(correct.filter(row=>row[i]===0).length<=1);for(const [i,row]of correct.entries())assert(b.explanation.includes(`${"ABC"[i]}は${row.map(n=>["CPU","I/O","待ち","完了"][n]).join("→")}`));return actual;}
